
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_b00_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_b00", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.233492814187661e+00, -4.236230190747658e+00, -4.231414480055268e+00, -4.207157725080658e+00, -4.138353205850541e+00, -3.974297081482190e+00, -3.621122048130159e+00, -2.952986847352567e+00, -1.997925019782346e+00, -1.274757363275225e+00, -9.681206500273213e-01, -5.578040825546909e-01, -6.210214269933177e-01, -5.321799154790910e-01, -3.185584613327369e-01, -2.200113676872953e-01, -1.736849889224785e-01, -1.159371951849138e-01, -7.664639415167243e-02, -5.154288528967776e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


